const CACHE='cardroom-lab-v7-screenshots';const FILES=['./','./index.html','./styles.css?v=2.1.1','./felt.css?v=2.1.1','./screenshot.css?v=2.1.1','./screenshot.mjs?v=2.1.1','./screenshot-ui.mjs?v=2.1.1','./vendor/tabler-1.7.5.min.css','./app.mjs?v=2.1.1','./engine.mjs','./worker.mjs','./icon.svg','./manifest.webmanifest'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)));self.skipWaiting();});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('cardroom-lab-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||!['http:','https:'].includes(u.protocol)||u.origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy)).catch(()=>{});}return r;}).catch(()=>caches.match(e.request).then(r=>r||Response.error())));});
